    letterSpacing: '2px'
  },
  courseBody: {
    padding: '20px'
  },
  courseRating: {
    color: '#fbbf24',
    fontSize: '13px',
    fontWeight: '800',
    marginBottom: '9px'
  },
  courseTitle: {
    color: '#f1f5f9',
    fontFamily: "Georgia,'Times New Roman',serif",
    fontSize: '20px',
    margin: '0 0 9px',
    lineHeight: '1.25'
  },
  courseDescription: {
    color: '#94a3b8',
    fontSize: '13px',
    lineHeight: '1.55',
    minHeight: '62px',
    margin: '0 0 15px'
  },
  skillsBox: {
    display: 'flex',
    flexDirection: 'column',
    gap: '6px',
    padding: '13px',
    borderRadius: '12px',
    background: '#161c1e',
    border: '1px solid rgba(255,255,255,0.04)',
    color: '#cbd5e1',
    fontSize: '12px',
    marginBottom: '17px'
  },
  courseFooter: {
    borderTop: '1px solid rgba(255,255,255,0.07)',
